const app=document.getElementById('app'),title=document.getElementById('title'),$=s=>document.querySelector(s);const allowedCurrencies=['IDR','USD'];const rates={USD:1,IDR:16000};data.settings.usdToIdrRate=Number(data.settings.usdToIdrRate)||16000;data.settings.adminDisplayCurrency='IDR';function adminRate(){return Number(data.settings.usdToIdrRate)||16000}function priceValue(p,c){if(p&&p.prices&&p.prices[c]!=null&&p.prices[c]!==''&&Number(p.prices[c])>0)return Number(p.prices[c]);return (Number(p&&p.price)||0)*rates[c]}function money(n){const c=data.settings.currency||'USD';return new Intl.NumberFormat(c==='IDR'?'id-ID':'en-US',{style:'currency',currency:c,maximumFractionDigits:c==='IDR'?0:2}).format((n||0))}function orderMoney(n,o){const c=o&&o.currency||'USD';const idr=c==='USD'?Number(n||0)*adminRate():Number(n||0);return new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(idr)}function moneyCurrency(n,c){c=c||'USD';return new Intl.NumberFormat(c==='IDR'?'id-ID':'en-US',{style:'currency',currency:c,maximumFractionDigits:c==='IDR'?0:2}).format((n||0))}function displayPrice(p){return money(priceValue(p,data.settings.currency||'USD'))}function siteSettingsPayload(){return{brand:data.settings.brand||'',currency:data.settings.currency||'USD',language:data.settings.language||'EN',whatsapp:data.settings.whatsapp||'',email:data.settings.email||'',address:data.settings.address||'',catalogID:data.settings.catalogID||'',catalogIntl:data.settings.catalogIntl||'',catalogWholesale:data.settings.catalogWholesale||'',usdToIdrRate:Number(data.settings.usdToIdrRate)||16000,adminDisplayCurrency:'IDR',social:data.settings.social||{},channels:data.settings.channels||[],appearance:data.settings.appearance||{},homepage:{taglineEN:data.taglineEN||'',taglineID:data.taglineID||'',introEyebrowEN:data.introEyebrowEN||'',introEyebrowID:data.introEyebrowID||'',showIntroEyebrow:data.showIntroEyebrow!==false,hero:(data.hero||[]).map(h=>({active:h.active!==false,showEyebrow:h.showEyebrow!==false,image:h.image||'',eyebrowEN:h.eyebrowEN||'',eyebrowID:h.eyebrowID||'',titleEN:h.titleEN||'',titleID:h.titleID||'',textEN:h.textEN||'',textID:h.textID||'',eyebrowColor:h.eyebrowColor||'',titleColor:h.titleColor||'',textColor:h.textColor||'',overlayColor:h.overlayColor||'#000000',overlayOpacity:Number(h.overlayOpacity??0.28),textPosition:h.textPosition||'left',button1LabelEN:h.button1LabelEN||'',button1LabelID:h.button1LabelID||'',button1Link:h.button1Link||'#shop',button2LabelEN:h.button2LabelEN||'',button2LabelID:h.button2LabelID||'',button2Link:h.button2Link||'#catalog'})),collections:(data.collections||[]).slice(0,3).map((x,i)=>({active:x.active!==false,image:x.image||'',titleEN:x.titleEN||'',titleID:x.titleID||'',link:x.link||'#shop',number:x.number||String(i+1).padStart(2,'0'),titleColor:x.titleColor||'',overlayColor:x.overlayColor||'#000000',overlayOpacity:Number(x.overlayOpacity??0.28)})),catalogSection:{...(data.catalogSection||{}),cards:(data.catalogSection?.cards||[]).slice(0,3)},processSection:{...(data.processSection||{}),cards:(data.processSection?.cards||[]).slice(0,4)},promoSection:{...(data.promoSection||{})}}}}
async function syncSiteSettings(){return apiFetch('/api/admin/settings',{method:'PATCH',body:JSON.stringify(siteSettingsPayload())})}
function safeLocalSave(){try{localStorage.setItem(KEY,JSON.stringify(data));return true}catch(err){console.warn('Local storage quota exceeded; production database remains source of truth.',err);return false}}function save(){safeLocalSave();syncSiteSettings().catch(err=>console.warn('Production sync failed:',err));render(active)}function logout(){sessionStorage.removeItem('palmaAdminToken');sessionStorage.removeItem('palmaAdminUser');location.href='index.html'}let active='overview';document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-tab]').forEach(x=>x.classList.remove('active'));b.classList.add('active');render(active=b.dataset.tab)});
const tabs={overview:'Ringkasan',orders:'Pesanan',products:'Produk & Stok',customers:'Pelanggan',wholesale:'Grosir / OEM',content:'Beranda & Hero',catalog:'Katalog / Flipbook',artisans:'Pengrajin & Proses',payments:'Pembayaran',invoices:'Invoice',packing:'Packing / QC',shipping:'Pengiriman',automation:'Otomatisasi',appearance:'Tampilan',media:'Media Library',channels:'Channel Penjualan',settings:'Pengaturan'};function render(t){document.getElementById('title').textContent=tabs[t]||t;({overview,orders,products,customers,wholesale,content,catalog,artisans,payments,invoices,packing,shipping,automation,appearance,media,channels,settings}[t]||overview)()}
function html(s){s=s??'';return s.replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#039;')}
function overview(){const paid=data.orders.filter(o=>o.paymentStatus==='LUNAS');const rev=paid.reduce((a,o)=>a+(o.currency==='USD'?Number(o.total||0)*adminRate():Number(o.total||0)),0);document.getElementById('app').innerHTML=`<div class="stats"><div class="stat"><small>Total Pesanan</small><strong>${data.orders.length}</strong></div><div class="stat"><small>Menunggu Verifikasi</small><strong>${data.orders.filter(o=>o.paymentStatus==='Menunggu Verifikasi').length}</strong></div><div class="stat"><small>Produk</small><strong>${data.products.length}</strong></div><div class="stat"><small>Pelanggan</small><strong>${data.customers.length}</strong></div><div class="stat"><small>Pendapatan Lunas (IDR)</small><strong>${new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(rev)}</strong></div></div><div class="panel"><h2>Alur otomatis</h2><p class="sectionNote">Pembayaran terverifikasi → LUNAS → reserve stok → invoice → packing/QC → shipping → tracking → selesai.</p><div class="automation"><div class="rule"><b>PEMBAYARAN LUNAS</b><p>Order diproses, stok di-reserve, invoice dan tugas packing dibuat.</p></div><div class="rule"><b>STOK MENIPIS</b><p>Produk dengan stok di bawah minimum diberi peringatan.</p></div><div class="rule"><b>DIKIRIM</b><p>Nomor resi disimpan dan notifikasi pengiriman disiapkan.</p></div><div class="rule"><b>TERKIRIM</b><p>Order dapat ditutup dan permintaan review dijadwalkan.</p></div></div></div><div class="panel"><div class="toolbar"><h2>Pesanan terbaru</h2><button class="btn" onclick="render('orders')">Lihat semua</button></div>${orderTable(8)}</div>`}
function orderTable(limit=100){return `<table class="table"><thead><tr><th>Order</th><th>Pelanggan</th><th>Total</th><th>Pembayaran</th><th>Status</th><th>Aksi</th></tr></thead><tbody>${data.orders.slice(0,limit).map(o=>`<tr><td>${o.id}</td><td>${html(o.customer.first)}<br>${html(o.customer.country)}</td><td>${orderMoney(o.total,o)}</td><td><span class="badge">${o.paymentStatus}</span></td><td><span class="badge">${o.orderStatus}</span></td><td><button class="btn" onclick="orderDetail('${o.id}')">Buka</button></td></tr>`).join('')||'<tr><td colspan="6">Belum ada pesanan.</td></tr>'}</tbody></table>`}
function orders(){document.getElementById('app').innerHTML=`<div class="panel"><div class="toolbar"><h2>Pesanan</h2><button class="btn" onclick="exportData()">Ekspor JSON</button></div>${orderTable()}</div>`}
function orderDetail(id){const o=data.orders.find(x=>x.id===id);if(!o)return;document.getElementById('app').innerHTML=`<div class="panel"><div class="toolbar"><div><span class="eyebrow">ORDER CONTROL CENTER</span><h2>${o.id}</h2></div><button class="btn" onclick="render('orders')">Kembali</button></div><div class="grid2"><div><h3>Pelanggan</h3><p>${html(o.customer.first)}<br>${html(o.customer.email)}<br>${html(o.customer.whatsapp||'')}<br>${html(o.customer.address||'')}<br>${html(o.customer.country)}</p><h3>Produk</h3>${o.items.map(i=>`<p>${html(i.name)} × ${i.qty} — ${orderMoney(i.price*i.qty,o)}</p>`).join('')}<p><b>Subtotal:</b> ${orderMoney(o.subtotal,o)}</p><p><b>Ongkir:</b> ${orderMoney(o.shipping,o)}</p><p><b>Total:</b> ${orderMoney(o.total,o)}</p></div><div><h3>Status</h3><p>Pembayaran: <b>${o.paymentStatus}</b></p><p>Order: <b>${o.orderStatus}</b></p><p>Invoice: <b>${o.invoiceNo||'Belum dibuat'}</b></p><p>Packing: <b>${o.packingNo||'Belum dibuat'}</b></p><label>Nomor Resi</label><input id="track" value="${o.tracking||''}" class="search"><label>Status Pengiriman</label><select id="ostatus" class="search"><option ${o.orderStatus==='DIPROSES'?'selected':''}>DIPROSES</option><option ${o.orderStatus==='QUALITY CHECK'?'selected':''}>QUALITY CHECK</option><option ${o.orderStatus==='PACKING'?'selected':''}>PACKING</option><option ${o.orderStatus==='READY TO SHIP'?'selected':''}>READY TO SHIP</option><option ${o.orderStatus==='DIKIRIM'?'selected':''}>DIKIRIM</option><option ${o.orderStatus==='TERKIRIM'?'selected':''}>TERKIRIM</option><option ${o.orderStatus==='SELESAI'?'selected':''}>SELESAI</option><option ${o.orderStatus==='DIBATALKAN'?'selected':''}>DIBATALKAN</option></select><button class="btn" onclick="saveOrder('${id}')">Simpan</button></div></div><div class="panel"><h3>Log Otomatisasi</h3><pre>${html((o.automationLog||[]).join('\n'))}</pre></div></div>`}
function saveOrder(id){const o=data.orders.find(x=>x.id===id);o.tracking=$('#track').value;o.orderStatus=$('#ostatus').value;o.automationLog=o.automationLog||[];if(o.orderStatus==='DIKIRIM'&&!o.tracking){alert('Masukkan nomor resi sebelum status DIKIRIM.');return}o.automationLog.push(new Date().toLocaleString('id-ID')+' — Status diubah menjadi '+o.orderStatus);if(o.orderStatus==='TERKIRIM')o.automationLog.push('Review request dijadwalkan');save()}
function products(){document.getElementById('app').innerHTML=`<div class="panel"><div class="toolbar"><div><h2>Produk & Stok</h2><p class="sectionNote">Kelola harga, stok, MOQ, berat, dimensi dan foto produk.</p></div><button class="btn" onclick="newProduct()">+ Tambah Produk</button></div><table class="table"><thead><tr><th>Produk</th><th>Kategori</th><th>Harga</th><th>Stok</th><th>Tipe</th><th>MOQ</th><th>Status</th><th>Aksi</th></tr></thead><tbody>${data.products.map(p=>`<tr><td>${html(p.name)}</td><td>${p.category}</td><td>${displayPrice(p)}</td><td>${p.stock}</td><td>${p.type==='retail'?'Retail':(p.type||'custom').toUpperCase()}</td><td>${['custom','wholesale','oem'].includes((p.type||'retail').toLowerCase())?p.moq:'—'}</td><td>${p.stock<=3?'<span class="bad">Stok rendah</span>':'Aktif'}</td><td><button class="btn" onclick="editProduct('${p.id}')">Edit</button></td></tr>`).join('')||'<tr><td colspan="8">Belum ada produk.</td></tr>'}</tbody></table></div>`}
function newProduct(){const p={id:'PR'+Date.now(),name:'Produk Rotan Baru',type:'retail',category:'home',price:0,stock:0,moq:1,prices:{IDR:0,USD:0},image:'../assets/hero-collection.png',description:'',weight:1,dimensions:''};data.products.push(p);editProduct(p.id)}function editProduct(id){const p=data.products.find(x=>x.id===id);document.getElementById('app').innerHTML=`<div class="panel"><div class="toolbar"><h2>Edit Produk</h2><button class="btn" onclick="render('products')">Kembali</button></div><div class="formGrid"><label>Nama Produk<input id="pn" value="${html(p.name)}" placeholder="Contoh: Keranjang Penyimpanan Rotan"></label><select id="pt" onchange="toggleMOQ()"><option value="retail" ${(p.type||'retail')==='retail'?'selected':''}>Retail</option><option value="custom" ${p.type==='custom'?'selected':''}>Custom</option><option value="wholesale" ${p.type==='wholesale'?'selected':''}>Wholesale</option><option value="oem" ${p.type==='oem'?'selected':''}>OEM</option></select><label>Kategori<select id="pc"><option value="home" ${p.category==='home'?'selected':''}>Home Decor</option><option value="vase" ${p.category==='vase'?'selected':''}>Vase & Planter</option><option value="basket" ${p.category==='basket'?'selected':''}>Baskets</option><option value="gift" ${p.category==='gift'?'selected':''}>Gifts</option></select></label><label>Harga Dasar USD (cadangan)<input id="pp" type="number" value="${p.price}" placeholder="Contoh: 85"></label><label>🇮🇩 Harga Indonesia (IDR)<input id="pidr" type="number" min="0" value="${p.prices?.IDR??''}" placeholder="Contoh: 1360000"></label><label>🌎 Harga Internasional (USD)<input id="pusd" type="number" step="0.01" min="0" value="${p.prices?.USD??p.price??''}" placeholder="Contoh: 85"></label><input id="ps" type="number" value="${p.stock}" placeholder="Contoh: 25"><input id="pm" type="number" min="1" value="${p.moq||1}" placeholder="Contoh: 50" ${['custom','wholesale','oem'].includes((p.type||'retail').toLowerCase())?'':'disabled'}><input id="pw" type="number" step=".1" value="${p.weight||0}" placeholder="Berat Produk (kg) — contoh: 1.2"><input id="pd" value="${html(p.dimensions||'')}" placeholder="Ukuran Produk (cm) — contoh: 35 × 35 × 30"><label class="fullField">Deskripsi Produk<textarea id="px" placeholder="Jelaskan material, fungsi, proses, dan karakter produk">${html(p.description||'')}</textarea></label></div><div class="priceNote"><b>Harga Indonesia & Internasional</b><br>Isi harga IDR dan USD secara terpisah. Isi keduanya secara manual sesuai harga yang Anda tetapkan. Harga Indonesia dan internasional tidak harus mengikuti kurs yang sama.</div><div class="heroCard"><b>Foto Produk</b><div class="heroPreview" id="prodPreview">${p.image?`<img src="${p.image}">`:'Belum ada foto'}</div><label class="upload">📷 Pilih Foto<input type="file" accept="image/*" onchange="productImage(event,'${p.id}')"></label></div><p class="sectionNote">MOQ hanya berlaku untuk Custom / Wholesale / OEM. Produk Retail dapat dibeli mulai 1 pcs selama stok tersedia.</p><button class="btn" onclick="saveProduct('${p.id}')">Simpan Produk</button></div>`}
function toggleMOQ(){const type=$('#pt').value;$('#pm').disabled=type==='retail';if(type==='retail')$('#pm').value=1}function productImage(e,id){const f=e.target.files[0];if(!f)return;if(f.size>4*1024*1024){alert('Maksimal 4 MB');return}const r=new FileReader();r.onload=ev=>{const p=data.products.find(x=>x.id===id);p.image=ev.target.result;document.getElementById('prodPreview').innerHTML=`<img src="${p.image}">`;saveNoRender()};r.readAsDataURL(f)}async function saveProduct(id){const p=data.products.find(x=>x.id===id);Object.assign(p,{name:$('#pn').value,type:$('#pt').value,category:$('#pc').value,price:Number($('#pp').value)||0,stock:Math.max(0,Number($('#ps').value)||0),moq:['custom','wholesale','oem'].includes($('#pt').value)?Math.max(1,Number($('#pm').value)||1):1,weight:Number($('#pw').value)||0,dimensions:$('#pd').value,description:$('#px').value,prices:{IDR:$('#pidr').value===''?null:Number($('#pidr').value),USD:$('#pusd').value===''?(Number($('#pp').value)||0):Number($('#pusd').value)}});try{await apiFetch('/api/admin/products',{method:'POST',body:JSON.stringify({id:p.id,sku:p.id,type:p.type,category:p.category,stock:p.stock,moq:p.moq,weight:p.weight,dimensions:p.dimensions,image:(p.image||'').replace(/^\.\.\//,''),name:p.name,nameEN:p.name,nameID:p.name,description:p.description,descriptionEN:p.description,descriptionID:p.description,priceIDR:p.prices.IDR,priceUSD:p.prices.USD})});alert('Produk tersimpan ke database production.');await loadProductionData()}catch(err){alert('Gagal menyimpan ke production API: '+err.message);save()} }function optimizeImageFile(file,max=1400,quality=.72){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=()=>reject(new Error('File gambar tidak dapat dibaca'));reader.onload=()=>{const img=new Image();img.onerror=()=>reject(new Error('Format gambar tidak dapat diproses'));img.onload=()=>{const scale=Math.min(1,max/Math.max(img.naturalWidth,img.naturalHeight));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.naturalWidth*scale));canvas.height=Math.max(1,Math.round(img.naturalHeight*scale));const ctx=canvas.getContext('2d');ctx.drawImage(img,0,0,canvas.width,canvas.height);resolve(canvas.toDataURL('image/jpeg',quality))};img.src=reader.result};reader.readAsDataURL(file)})}
function saveNoRender(){safeLocalSave()}
function customers(){document.getElementById('app').innerHTML=`<div class="panel"><h2>Pelanggan</h2><table class="table"><thead><tr><th>Nama</th><th>Email</th><th>Negara</th><th>Pesanan</th></tr></thead><tbody>${data.customers.map(c=>`<tr><td>${html(c.name)}</td><td>${html(c.email)}</td><td>${html(c.country)}</td><td>${c.orders}</td></tr>`).join('')||'<tr><td colspan="4">Belum ada pelanggan.</td></tr>'}</tbody></table></div>`}
function wholesale(){document.getElementById('app').innerHTML=`<div class="panel"><div class="toolbar"><h2>Grosir / OEM</h2><span>Alur: Baru → Dihubungi → Penawaran → Negosiasi → Disetujui → Produksi → Selesai</span></div><table class="table"><thead><tr><th>No</th><th>Nama/Perusahaan</th><th>Email</th><th>Negara</th><th>Qty</th><th>Status</th></tr></thead><tbody>${data.quotes.map(q=>`<tr><td>${q.id}</td><td>${html(q.name)}</td><td>${html(q.email)}</td><td>${html(q.country)}</td><td>${q.qty||'-'}</td><td><select onchange="quoteStatus('${q.id}',this.value)">${['NEW','CONTACTED','QUOTATION SENT','NEGOTIATION','APPROVED','PRODUCTION','COMPLETED','CANCELLED'].map(s=>`<option ${q.status===s?'selected':''}>${s}</option>`).join('')}</select></td></tr>`).join('')||'<tr><td colspan="6">Belum ada inquiry.</td></tr>'}</tbody></table></div>`}function quoteStatus(id,v){const q=data.quotes.find(x=>x.id===id);q.status=v;saveNoRender();render('wholesale')}
function content(){document.getElementById('app').innerHTML=`<div class="panel"><div class="heroCard"><div class="toolbar"><div><h3>Label Section Pilihan PALMA ROTAN</h3><p class="sectionNote">Bisa diganti atau disembunyikan tanpa mengubah judul utama.</p></div><label><input id="showIntro" type="checkbox" ${data.showIntroEyebrow!==false?'checked':''}> Tampilkan label</label></div><div class="formGrid"><label>🇬🇧 English<input id="introEN" value="${html(data.introEyebrowEN||'THE PALMA EDIT')}"></label><label>🇮🇩 Indonesia<input id="introID" value="${html(data.introEyebrowID||'PILIHAN PALMA ROTAN')}"></label></div><button class="btn" onclick="saveIntroLabel()">Simpan Label</button></div></div><div class="panel"><div class="toolbar"><div><h2>Hero Slider</h2><p class="sectionNote">Setiap slide memiliki foto, teks EN/ID, warna sendiri, overlay, posisi teks, dan tombol.</p></div><button class="btn" onclick="saveHero()">Simpan Semua</button></div>${data.hero.slice(0,3).map((h,i)=>{const eye=h.eyebrowColor||'#eadac5',title=h.titleColor||'#ffffff',txt=h.textColor||'#eee7df',ov=h.overlayColor||'#000000',op=Math.round(Number(h.overlayOpacity??0.28)*100);return `<div class="heroCard"><div class="heroSlideAdminHead"><strong>SLIDE ${String(i+1).padStart(2,'0')}</strong><label><input id="ha${i}" type="checkbox" ${h.active!==false?'checked':''}> Aktifkan slide</label></div><div class="heroTop"><div><div class="heroPreview" id="hp${i}">${h.image?`<img src="${h.image}">`:'Belum ada foto'}</div><label class="upload">📷 Pilih Foto<input id="hf${i}" type="file" accept="image/*" onchange="heroFile(${i})"></label><span class="uploadName" id="hn${i}">${h.image?'Foto tersimpan':'Belum dipilih'}</span></div><div class="heroFields"><label>🇬🇧 Label / Eyebrow English<input id="heEN${i}" value="${html(h.eyebrowEN||h.eyebrow||'')}"></label><label>🇮🇩 Label / Eyebrow Indonesia<input id="heID${i}" value="${html(h.eyebrowID||h.eyebrow||'')}"></label><label><input id="hs${i}" type="checkbox" ${h.showEyebrow!==false?'checked':''}> Tampilkan label</label><label>🇬🇧 Judul English<textarea id="htEN${i}">${html(h.titleEN||h.title||'')}</textarea></label><label>🇮🇩 Judul Indonesia<textarea id="htID${i}">${html(h.titleID||h.title||'')}</textarea></label><label>🇬🇧 Deskripsi English<textarea id="hxEN${i}">${html(h.textEN||h.text||'')}</textarea></label><label>🇮🇩 Deskripsi Indonesia<textarea id="hxID${i}">${html(h.textID||h.text||'')}</textarea></label></div></div><div class="heroStyleGrid"><div><h4>Warna & Tampilan</h4><div class="colorGrid"><label class="colorField"><span><b>Warna Label</b><small>Eyebrow slide ini</small></span><input id="hcEye${i}" type="color" value="${eye}"></label><label class="colorField"><span><b>Warna Judul</b><small>Judul slide ini</small></span><input id="hcTitle${i}" type="color" value="${title}"></label><label class="colorField"><span><b>Warna Deskripsi</b><small>Teks deskripsi</small></span><input id="hcText${i}" type="color" value="${txt}"></label><label class="colorField"><span><b>Warna Overlay</b><small>Lapisan di atas foto</small></span><input id="hcOverlay${i}" type="color" value="${ov}"></label></div><label class="rangeField">Kegelapan Overlay <input id="ho${i}" type="range" min="0" max="80" value="${op}"><span id="hov${i}">${op}%</span></label><label>Posisi Teks<select id="hpPos${i}"><option value="left" ${(h.textPosition||'left')==='left'?'selected':''}>Kiri</option><option value="center" ${h.textPosition==='center'?'selected':''}>Tengah</option><option value="right" ${h.textPosition==='right'?'selected':''}>Kanan</option></select></label></div><div><h4>Tombol Slide</h4><label>Button 1 EN<input id="hb1EN${i}" value="${html(h.button1LabelEN||'Shop Now')}"></label><label>Button 1 ID<input id="hb1ID${i}" value="${html(h.button1LabelID||'Belanja Sekarang')}"></label><label>Link Button 1<input id="hb1Link${i}" value="${html(h.button1Link||'#shop')}"></label><label>Button 2 EN<input id="hb2EN${i}" value="${html(h.button2LabelEN||'View Catalog')}"></label><label>Button 2 ID<input id="hb2ID${i}" value="${html(h.button2LabelID||'Lihat Katalog')}"></label><label>Link Button 2<input id="hb2Link${i}" value="${html(h.button2Link||'#catalog')}"></label></div></div></div>`}).join('')}</div><div class="panel"><div class="toolbar"><div><h2>Pilihan PALMA ROTAN</h2><p class="sectionNote">Kelola 3 kartu koleksi: foto, judul EN/ID, nomor, warna judul, overlay, dan tautan.</p></div><button class="btn" onclick="saveCollections()">Simpan Pilihan</button></div>${[0,1,2].map(i=>{const x=data.collections?.[i]||{};const ov=x.overlayColor||'#000000',op=Math.round(Number(x.overlayOpacity??0.28)*100);return `<div class="heroCard"><div class="heroSlideAdminHead"><strong>KOLEKSI ${String(i+1).padStart(2,'0')}</strong><label><input id="ca${i}" type="checkbox" ${x.active!==false?'checked':''}> Aktifkan</label></div><div class="heroTop"><div><div class="heroPreview" id="cp${i}">${x.image?`<img src="${x.image}">`:'Belum ada foto'}</div><label class="upload">📷 Pilih Foto<input id="cf${i}" type="file" accept="image/*" onchange="collectionFile(${i})"></label><span class="uploadName" id="cn${i}">${x.image?'Foto tersimpan':'Belum dipilih'}</span></div><div class="heroFields"><label>Nomor<input id="cnum${i}" value="${html(x.number||String(i+1).padStart(2,'0'))}"></label><label>🇬🇧 Judul English<input id="ctEN${i}" value="${html(x.titleEN||['Natural Living','Vase & Planter','Gifts & Hampers'][i])}"></label><label>🇮🇩 Judul Indonesia<input id="ctID${i}" value="${html(x.titleID||['Kehidupan Natural','Vas & Pot','Hadiah & Hampers'][i])}"></label><label>Link / Tujuan<input id="clink${i}" value="${html(x.link||'#shop')}"></label></div></div><div class="heroStyleGrid"><div><h4>Warna & Tampilan</h4><div class="colorGrid"><label class="colorField"><span><b>Warna Judul</b><small>Judul kartu</small></span><input id="ccTitle${i}" type="color" value="${x.titleColor||'#ffffff'}"></label><label class="colorField"><span><b>Warna Overlay</b><small>Lapisan foto</small></span><input id="ccOverlay${i}" type="color" value="${ov}"></label></div><label class="rangeField">Kegelapan Overlay <input id="co${i}" type="range" min="0" max="80" value="${op}"><span id="cov${i}">${op}%</span></label></div></div></div>`}).join('')}</div><div class="panel"><h2>Tagline</h2><div class="formGrid"><label>🇬🇧 English<input id="tEN" value="${html(data.taglineEN||'Handcrafted in Indonesia · Designed for the World')}"></label><label>🇮🇩 Indonesia<input id="tID" value="${html(data.taglineID||'Dibuat dengan tangan di Indonesia · Dirancang untuk Dunia')}"></label></div></div>`}async function catalogSectionFile(i){const f=$("#cgF"+i).files[0];if(!f)return;if(f.size>8*1024*1024){alert("Maksimal 8 MB");return}try{const image=await optimizeImageFile(f,1200,.72);data.catalogSection.cards[i].image=image;document.getElementById("cgP"+i).innerHTML=`<img src="${image}">`;safeLocalSave()}catch(err){alert("Foto catalog gagal diproses: "+err.message)}}async function processSectionFile(i){const f=$("#prF"+i).files[0];if(!f)return;if(f.size>8*1024*1024){alert("Maksimal 8 MB");return}try{const image=await optimizeImageFile(f,1200,.72);data.processSection.cards[i].image=image;document.getElementById("prP"+i).innerHTML=`<img src="${image}">`;safeLocalSave()}catch(err){alert("Foto process gagal diproses: "+err.message)}}async function promoSectionFile(){const f=$("#pmF").files[0];if(!f)return;if(f.size>8*1024*1024){alert("Maksimal 8 MB");return}try{const image=await optimizeImageFile(f,1600,.75);data.promoSection.image=image;document.getElementById("pmP").innerHTML=`<img src="${image}">`;safeLocalSave()}catch(err){alert("Foto promo gagal diproses: "+err.message)}}async function saveHomepageSections(){try{data.catalogSection.bgColor=$("#cgBG").value;data.catalogSection.overlayOpacity=Number($("#cgOP").value)/100;data.catalogSection.cards=[0,1,2].map(i=>({active:$("#cgA"+i).checked,image:data.catalogSection.cards[i]?.image||"",number:$("#cgN"+i).value.trim(),icon:$("#cgI"+i).value.trim(),titleEN:$("#cgTE"+i).value,titleID:$("#cgTI"+i).value,descEN:$("#cgDE"+i).value,descID:$("#cgDI"+i).value,link:$("#cgL"+i).value.trim(),titleColor:$("#cgTC"+i).value,descColor:$("#cgDC"+i).value,overlayColor:$("#cgOC"+i).value}));data.processSection.eyebrowEN=$("#prEyeE").value;data.processSection.eyebrowID=$("#prEyeI").value;data.processSection.titleEN=$("#prTitleE").value;data.processSection.titleID=$("#prTitleI").value;data.processSection.bgColor=$("#prSecBG").value;data.processSection.titleColor=$("#prSecTC").value;data.processSection.textColor=$("#prSecXC").value;data.processSection.cards=[0,1,2,3].map(i=>({image:data.processSection.cards[i]?.image||"",titleEN:$("#prTE"+i).value,titleID:$("#prTI"+i).value,descEN:$("#prDE"+i).value,descID:$("#prDI"+i).value,bgColor:$("#prBG"+i).value,titleColor:$("#prTC"+i).value,textColor:$("#prXC"+i).value}));Object.assign(data.promoSection,{eyebrowEN:$("#pmEE").value,eyebrowID:$("#pmEI").value,titleEN:$("#pmTE").value,titleID:$("#pmTI").value,textEN:$("#pmDE").value,textID:$("#pmDI").value,buttonEN:$("#pmBE").value,buttonID:$("#pmBI").value,link:$("#pmL").value.trim()||"#contact",bgColor:$("#pmBG").value,eyebrowColor:$("#pmEC").value,titleColor:$("#pmTC").value,textColor:$("#pmXC").value,buttonBg:$("#pmBC").value,buttonColor:$("#pmBT").value,overlayColor:$("#pmOC").value});safeLocalSave();await syncSiteSettings();render(active);alert("Catalog, Craft Process, dan Promo berhasil tersimpan ke database production.")}catch(err){console.error(err);alert("Gagal menyimpan Beranda: "+err.message)}renderHomepageCmsPanels()}function renderHomepageCmsPanels(){const box=document.createElement("div");box.id="homepageCmsPanels";box.innerHTML=`<div class="panel"><div class="toolbar"><div><h2>Digital Catalog — 3 Slot</h2><p class="sectionNote">Foto, teks, link dan warna tiap kartu.</p></div><button class="btn" onclick="saveHomepageSections()">Simpan Semua</button></div>${[0,1,2].map(i=>{const x=data.catalogSection.cards[i]||{};return `<div class="heroCard"><b>CATALOG ${i+1}</b><div class="heroTop"><div><div class="heroPreview" id="cgP${i}">${x.image?`<img src="${x.image}">`:"Belum ada foto"}</div><label class="upload">📷 Foto<input id="cgF${i}" type="file" accept="image/*" onchange="catalogSectionFile(${i})"></label></div><div class="heroFields"><label>Nomor<input id="cgN${i}" value="${html(x.number||String(i+1).padStart(2,"0"))}"></label><label>Ikon<input id="cgI${i}" value="${html(x.icon||["ID","EN","B2B"][i])}"></label><label>Judul EN<input id="cgTE${i}" value="${html(x.titleEN||"")}"></label><label>Judul ID<input id="cgTI${i}" value="${html(x.titleID||"")}"></label><label>Deskripsi EN<textarea id="cgDE${i}">${html(x.descEN||"")}</textarea></label><label>Deskripsi ID<textarea id="cgDI${i}">${html(x.descID||"")}</textarea></label><label>Link<input id="cgL${i}" value="${html(x.link||"")}"></label></div></div><div class="colorGrid"><label class="colorField">Judul <input id="cgTC${i}" type="color" value="${x.titleColor||"#ffffff"}"></label><label class="colorField">Deskripsi <input id="cgDC${i}" type="color" value="${x.descColor||"#c7bdb2"}"></label><label class="colorField">Overlay <input id="cgOC${i}" type="color" value="${x.overlayColor||"#000000"}"></label></div></div>`}).join("")}<div class="panelNote">Latar <input id="cgBG" type="color" value="${data.catalogSection.bgColor||"#f5eee4"}"> Overlay <input id="cgOP" type="range" min="0" max="80" value="${Math.round(Number(data.catalogSection.overlayOpacity??.12)*100)}"></div></div><div class="panel"><div class="toolbar"><div><h2>Craft Process — 4 Slot</h2><p class="sectionNote">Bahan → pembuatan → quality control → packing.</p></div></div><div class="formGrid"><label>Eyebrow EN<input id="prEyeE" value="${html(data.processSection.eyebrowEN||"")}"></label><label>Eyebrow ID<input id="prEyeI" value="${html(data.processSection.eyebrowID||"")}"></label><label>Judul EN<input id="prTitleE" value="${html(data.processSection.titleEN||"")}"></label><label>Judul ID<input id="prTitleI" value="${html(data.processSection.titleID||"")}"></label><label>Warna Latar<input id="prSecBG" type="color" value="${data.processSection.bgColor||"#eee4d7"}"></label><label>Warna Judul<input id="prSecTC" type="color" value="${data.processSection.titleColor||"#211a15"}"></label><label>Warna Teks<input id="prSecXC" type="color" value="${data.processSection.textColor||"#6f6257"}"></label></div>${[0,1,2,3].map(i=>{const x=data.processSection.cards[i]||{};return `<div class="heroCard"><b>PROCESS ${i+1}</b><div class="heroTop"><div><div class="heroPreview" id="prP${i}">${x.image?`<img src="${x.image}">`:"Belum ada foto"}</div><label class="upload">📷 Foto<input id="prF${i}" type="file" accept="image/*" onchange="processSectionFile(${i})"></label></div><div class="heroFields"><label>Judul EN<input id="prTE${i}" value="${html(x.titleEN||"")}"></label><label>Judul ID<input id="prTI${i}" value="${html(x.titleID||"")}"></label><label>Deskripsi EN<textarea id="prDE${i}">${html(x.descEN||"")}</textarea></label><label>Deskripsi ID<textarea id="prDI${i}">${html(x.descID||"")}</textarea></label></div></div><div class="colorGrid"><label class="colorField">Latar <input id="prBG${i}" type="color" value="${x.bgColor||"#f8f2e9"}"></label><label class="colorField">Judul <input id="prTC${i}" type="color" value="${x.titleColor||"#211a15"}"></label><label class="colorField">Teks <input id="prXC${i}" type="color" value="${x.textColor||"#6f6257"}"></label></div></div>`}).join("")}</div><div class="panel"><div class="toolbar"><div><h2>Promo Banner — 1 Slot</h2><p class="sectionNote">Foto brosur promo + teks, tombol dan warna.</p></div></div><div class="heroTop"><div><div class="heroPreview" id="pmP">${data.promoSection.image?`<img src="${data.promoSection.image}">`:"Belum ada foto"}</div><label class="upload">📷 Foto<input id="pmF" type="file" accept="image/*" onchange="promoSectionFile()"></label></div><div class="heroFields"><label>Eyebrow EN<input id="pmEE" value="${html(data.promoSection.eyebrowEN||"")}"></label><label>Eyebrow ID<input id="pmEI" value="${html(data.promoSection.eyebrowID||"")}"></label><label>Judul EN<textarea id="pmTE">${html(data.promoSection.titleEN||"")}</textarea></label><label>Judul ID<textarea id="pmTI">${html(data.promoSection.titleID||"")}</textarea></label><label>Deskripsi EN<textarea id="pmDE">${html(data.promoSection.textEN||"")}</textarea></label><label>Deskripsi ID<textarea id="pmDI">${html(data.promoSection.textID||"")}</textarea></label><label>Button EN<input id="pmBE" value="${html(data.promoSection.buttonEN||"")}"></label><label>Button ID<input id="pmBI" value="${html(data.promoSection.buttonID||"")}"></label><label>Link<input id="pmL" value="${html(data.promoSection.link||"#contact")}"></label></div></div><div class="colorGrid"><label class="colorField">Background <input id="pmBG" type="color" value="${data.promoSection.bgColor||"#eee4d7"}"></label><label class="colorField">Eyebrow <input id="pmEC" type="color" value="${data.promoSection.eyebrowColor||"#8b6b4e"}"></label><label class="colorField">Judul <input id="pmTC" type="color" value="${data.promoSection.titleColor||"#211a15"}"></label><label class="colorField">Teks <input id="pmXC" type="color" value="${data.promoSection.textColor||"#6f6257"}"></label><label class="colorField">Tombol BG <input id="pmBC" type="color" value="${data.promoSection.buttonBg||"#211a15"}"></label><label class="colorField">Tombol teks <input id="pmBT" type="color" value="${data.promoSection.buttonColor||"#ffffff"}"></label><label class="colorField">Overlay <input id="pmOC" type="color" value="${data.promoSection.overlayColor||"#000000"}"></label></div><button class="btn" onclick="saveHomepageSections()">Simpan Catalog / Process / Promo</button></div>`;document.getElementById("app").appendChild(box)}async function saveIntroLabel(){data.showIntroEyebrow=$('#showIntro').checked;data.introEyebrowEN=$('#introEN').value.trim();data.introEyebrowID=$('#introID').value.trim();safeLocalSave();try{await syncSiteSettings();alert('Label tersimpan ke database production.')}catch(err){alert('Gagal sinkronisasi label: '+err.message)}render('content')}async function heroFile(i){const f=$('#hf'+i).files[0];if(!f)return;if(f.size>8*1024*1024){alert('Maksimal 8 MB');return}try{const image=await optimizeImageFile(f,1400,.72);data.hero[i].image=image;document.getElementById('hp'+i).innerHTML=`<img src="${image}">`;document.getElementById('hn'+i).textContent=f.name+' (optimized)';safeLocalSave();await syncSiteSettings();alert('Foto Hero berhasil disinkronkan ke database production.')}catch(err){console.error(err);alert('Foto Hero gagal disinkronkan: '+err.message)}}async function collectionFile(i){const f=$('#cf'+i).files[0];if(!f)return;if(f.size>8*1024*1024){alert('Maksimal 8 MB');return}try{const final=await optimizeImageFile(f,1200,.65);if(!data.collections)data.collections=[];if(!data.collections[i])data.collections[i]={};data.collections[i].image=final;document.getElementById('cp'+i).innerHTML=`<img src="${final}">`;document.getElementById('cn'+i).textContent=f.name+' (optimized)';safeLocalSave();await syncSiteSettings();alert('Foto Collection berhasil disinkronkan ke database production.')}catch(err){console.error(err);alert('Foto Collection gagal disinkronkan: '+err.message)}}async function saveCollections(){try{if(!data.collections)data.collections=[];for(let i=0;i<3;i++){const x=data.collections[i]||{};x.active=$('#ca'+i).checked;x.number=$('#cnum'+i).value.trim()||String(i+1).padStart(2,'0');x.titleEN=$('#ctEN'+i).value.trim();x.titleID=$('#ctID'+i).value.trim();x.link=$('#clink'+i).value.trim()||'#shop';x.titleColor=$('#ccTitle'+i).value;x.overlayColor=$('#ccOverlay'+i).value;x.overlayOpacity=Number($('#co'+i).value)/100;data.collections[i]=x}safeLocalSave();await syncSiteSettings();render(active);alert('Pilihan PALMA ROTAN tersimpan ke database production. Website pengunjung akan mengikuti data terbaru setelah refresh.')}catch(err){console.error(err);alert('Gagal menyimpan Pilihan PALMA ROTAN: '+err.message)}}async function saveHero(){try{data.taglineEN=$('#tEN').value;data.taglineID=$('#tID').value;data.hero.forEach((h,i)=>{h.showEyebrow=$('#hs'+i).checked;h.eyebrowEN=$('#heEN'+i).value.trim();h.eyebrowID=$('#heID'+i).value.trim();h.titleEN=$('#htEN'+i).value;h.titleID=$('#htID'+i).value;h.textEN=$('#hxEN'+i).value;h.textID=$('#hxID'+i).value;h.eyebrow=h.eyebrowEN;h.title=h.titleEN;h.text=h.textEN;h.active=$('#ha'+i).checked;h.eyebrowColor=$('#hcEye'+i).value;h.titleColor=$('#hcTitle'+i).value;h.textColor=$('#hcText'+i).value;h.overlayColor=$('#hcOverlay'+i).value;h.overlayOpacity=Number($('#ho'+i).value)/100;h.textPosition=$('#hpPos'+i).value;h.button1LabelEN=$('#hb1EN'+i).value;h.button1LabelID=$('#hb1ID'+i).value;h.button1Link=$('#hb1Link'+i).value||'#shop';h.button2LabelEN=$('#hb2EN'+i).value;h.button2LabelID=$('#hb2ID'+i).value;h.button2Link=$('#hb2Link'+i).value||'#catalog'});safeLocalSave();await syncSiteSettings();render(active);alert('Hero Slider tersimpan ke database production. Website pengunjung akan mengikuti data terbaru setelah refresh.')}catch(err){console.error(err);alert('Gagal menyimpan Hero Slider: '+err.message)}}function saveNoRender(){safeLocalSave()}
function catalog(){document.getElementById('app').innerHTML=`<div class="panel"><h2>Katalog / Flipbook</h2><p class="sectionNote">Tautan dapat diganti tanpa mengedit kode. Gunakan URL Flipbook yang sebenarnya.</p><div class="formGrid"><input id="cid" value="${html(data.settings.catalogID)}" placeholder="Katalog Indonesia"><input id="cen" value="${html(data.settings.catalogIntl)}" placeholder="International Catalog"><input id="cwh" value="${html(data.settings.catalogWholesale)}" placeholder="Wholesale Catalog"></div><button class="btn" onclick="saveCatalog()">Simpan Tautan</button></div>`}async function saveCatalog(){Object.assign(data.settings,{catalogID:$('#cid').value.trim(),catalogIntl:$('#cen').value.trim(),catalogWholesale:$('#cwh').value.trim()});safeLocalSave();try{await syncSiteSettings();alert('Tautan katalog tersimpan ke database production.')}catch(err){alert('Gagal sinkronisasi katalog: '+err.message)}}
function artisans(){document.getElementById('app').innerHTML=`<div class="panel"><h2>Pengrajin & Proses</h2><p class="sectionNote">Profil pengrajin dapat ditambah dengan foto dan cerita. Tahapan proses: Pilih, Persiapan, Membentuk, Menganyam, Penyelesaian, Pemeriksaan Mutu.</p><div class="formGrid"><input id="an" placeholder="Nama pengrajin"><input id="ar" placeholder="Peran"><input id="al" placeholder="Lokasi"><input id="ay" placeholder="Tahun pengalaman"><textarea id="as" placeholder="Cerita pengrajin"></textarea></div><button class="btn" onclick="addArtisan()">Tambah Pengrajin</button><div>${data.artisans.map((a,i)=>`<div class="rule"><b>${html(a.name)}</b> · ${html(a.role)} · ${html(a.location)}<p>${html(a.story)}</p></div>`).join('')||'<p>Belum ada profil.</p>'}</div></div>`}function addArtisan(){data.artisans.push({name:$('#an').value,role:$('#ar').value,location:$('#al').value,years:$('#ay').value,story:$('#as').value});save()}
function payments(){const pending=data.orders.filter(o=>o.paymentStatus==='Menunggu Verifikasi');document.getElementById('app').innerHTML=`<div class="panel"><h2>Verifikasi Pembayaran</h2><p class="sectionNote">Transfer bank harus disetujui admin. Gateway production akan mengubah status melalui webhook terverifikasi.</p>${pending.map(o=>`<div class="rule"><b>${o.id} · ${orderMoney(o.total,o)}</b><p>${html(o.customer.first)} · ${html(o.customer.email)} · ${o.paymentMethod}</p><button class="btn" onclick="approvePayment('${o.id}')">Tandai Lunas</button> <button class="btn danger" onclick="rejectPayment('${o.id}')">Tolak</button></div>`).join('')||'<p>Tidak ada pembayaran yang menunggu verifikasi.</p>'}</div><div class="panel"><h2>Riwayat Pembayaran</h2>${orderTable()}</div>`}
function approvePayment(id){const o=data.orders.find(x=>x.id===id);if(!o)return;if(o.paymentStatus==='LUNAS')return;o.paymentStatus='LUNAS';o.orderStatus='DIPROSES';o.stockReserved=true;o.invoiceNo='INV-'+id;o.packingNo='PK-'+id;o.automationLog=o.automationLog||[];o.automationLog.push('Pembayaran diverifikasi admin','Stok di-reserve','Invoice dibuat '+o.invoiceNo,'Packing task dibuat '+o.packingNo);o.items.forEach(i=>{const p=data.products.find(p=>p.id===i.id);if(p)p.stock=Math.max(0,p.stock-i.qty)});save();alert('Pembayaran disetujui. Invoice, stok dan packing task diproses otomatis.')}function rejectPayment(id){const o=data.orders.find(x=>x.id===id);o.paymentStatus='DITOLAK';o.orderStatus='MENUNGGU PEMBAYARAN';o.automationLog=(o.automationLog||[]).concat('Pembayaran ditolak admin');save()}
function invoices(){const rows=data.orders.filter(o=>o.invoiceNo);document.getElementById('app').innerHTML=`<div class="panel"><h2>Invoice</h2><table class="table"><thead><tr><th>Invoice</th><th>Order</th><th>Pelanggan</th><th>Total</th><th>Aksi</th></tr></thead><tbody>${rows.map(o=>`<tr><td>${o.invoiceNo}</td><td>${o.id}</td><td>${html(o.customer.first)}</td><td>${money(o.total)}</td><td><button class="btn" onclick="invoice('${o.id}')">Lihat / Cetak</button></td></tr>`).join('')||'<tr><td colspan="5">Belum ada invoice.</td></tr>'}</tbody></table></div>`}function invoice(id){const o=data.orders.find(x=>x.id===id);document.getElementById('app').innerHTML=`<div class="panel invoice"><div class="toolbar"><h2>PALMA ROTAN — INVOICE</h2><button class="btn" onclick="window.print()">Cetak / Simpan PDF</button></div><div class="invoiceHead"><p><b>${o.invoiceNo}</b><br>Order ${o.id}<br>${new Date(o.created).toLocaleDateString('id-ID')}</p><p><b>Bill To</b><br>${html(o.customer.first)}<br>${html(o.customer.email)}<br>${html(o.customer.country)}</p></div><hr>${o.items.map(i=>`<p>${html(i.name)} × ${i.qty} — ${orderMoney(i.price*i.qty,o)}</p>`).join('')}<p>Subtotal produk: ${orderMoney(o.subtotal,o)}</p><p>Ongkir: ${orderMoney(o.shipping,o)}</p><h2>Total: ${orderMoney(o.total,o)}</h2><p>Status pembayaran: ${o.paymentStatus}</p><p>Catatan: Harga produk tidak termasuk ongkir; bea masuk/pajak tujuan dapat berlaku.</p></div>`}
function packing(){const rows=data.orders.filter(o=>o.packingNo&&o.orderStatus!=='SELESAI'&&o.orderStatus!=='DIBATALKAN');document.getElementById('app').innerHTML=`<div class="panel"><h2>Packing / QC</h2><p class="sectionNote">Hanya order yang pembayarannya LUNAS dibuatkan tugas packing.</p><table class="table"><thead><tr><th>Packing</th><th>Order</th><th>QC</th><th>Berat Aktual</th><th>Dimensi</th><th>Aksi</th></tr></thead><tbody>${rows.map(o=>`<tr><td>${o.packingNo}</td><td>${o.id}</td><td>${o.qcStatus||'BELUM QC'}</td><td>${o.actualWeight||'—'}</td><td>${o.packageDimensions||'—'}</td><td><button class="btn" onclick="qc('${o.id}')">QC / Packing</button></td></tr>`).join('')||'<tr><td colspan="6">Belum ada tugas packing.</td></tr>'}</tbody></table></div>`}function qc(id){const o=data.orders.find(x=>x.id===id);document.getElementById('app').innerHTML=`<div class="panel"><h2>${o.packingNo} · QC / Packing</h2><div class="formGrid"><select id="qc"><option>PASS</option><option>REWORK</option></select><input id="aw" type="number" step=".1" value="${o.actualWeight||''}" placeholder="Berat aktual kg"><input id="ad" value="${o.packageDimensions||''}" placeholder="Dimensi paket cm"><input id="pcourier" value="${o.courier||''}" placeholder="Kurir (opsional)"></div><button class="btn" onclick="saveQC('${id}')">Simpan QC & Packing</button></div>`}function saveQC(id){const o=data.orders.find(x=>x.id===id);o.qcStatus=$('#qc').value;o.actualWeight=$('#aw').value;o.packageDimensions=$('#ad').value;o.courier=$('#pcourier').value;o.orderStatus=o.qcStatus==='PASS'?'PACKING':'QUALITY CHECK';o.automationLog=(o.automationLog||[]).concat('QC: '+o.qcStatus,'Data packing diperbarui');save()}
function shipping(){const rows=data.orders.filter(o=>o.orderStatus==='PACKING'||o.orderStatus==='READY TO SHIP'||o.orderStatus==='DIKIRIM'||o.orderStatus==='TERKIRIM');document.getElementById('app').innerHTML=`<div class="panel"><h2>Pengiriman</h2><p class="sectionNote">Harga ongkir customer dihitung saat checkout. Pada production, tarif harus berasal dari API courier dan berat/dimensi aktual.</p><table class="table"><thead><tr><th>Order</th><th>Negara</th><th>Kurir</th><th>Resi</th><th>Status</th><th>Aksi</th></tr></thead><tbody>${rows.map(o=>`<tr><td>${o.id}</td><td>${html(o.customer.country)}</td><td>${html(o.courier||'—')}</td><td>${html(o.tracking||'—')}</td><td>${o.orderStatus}</td><td><button class="btn" onclick="ship('${o.id}')">Update</button></td></tr>`).join('')||'<tr><td colspan="6">Belum ada order siap kirim.</td></tr>'}</tbody></table></div>`}function ship(id){const o=data.orders.find(x=>x.id===id);document.getElementById('app').innerHTML=`<div class="panel"><h2>Pengiriman ${o.id}</h2><div class="formGrid"><input id="courier" value="${o.courier||''}" placeholder="Kurir"><input id="tracking2" value="${o.tracking||''}" placeholder="Nomor resi"><select id="shipstatus"><option>READY TO SHIP</option><option>DIKIRIM</option><option>TERKIRIM</option></select></div><button class="btn" onclick="saveShip('${id}')">Simpan Pengiriman</button></div>`}function saveShip(id){const o=data.orders.find(x=>x.id===id);o.courier=$('#courier').value;o.tracking=$('#tracking2').value;o.orderStatus=$('#shipstatus').value;o.automationLog=(o.automationLog||[]).concat('Shipping diperbarui: '+o.orderStatus);save()}
function automation(){document.getElementById('app').innerHTML=`<div class="panel"><h2>Otomatisasi</h2><div class="automation"><div class="rule"><b>Payment = LUNAS</b><p>Reserve stok → Invoice → Packing Task → Order DIPROSES.</p></div><div class="rule"><b>Stock &lt; 3</b><p>Tampilkan peringatan stok rendah.</p></div><div class="rule"><b>QC PASS</b><p>Order masuk PACKING.</p></div><div class="rule"><b>DIKIRIM</b><p>Tracking disimpan dan notifikasi disiapkan.</p></div><div class="rule"><b>TERKIRIM</b><p>Review request dijadwalkan.</p></div><div class="rule"><b>WHOLESALE / OEM</b><p>Inquiry → Quotation → Approval → Production → QC → Shipping.</p></div></div></div>`}
function appearance(){const a=data.settings.appearance||{};const fields=[['headerBg','Warna Header (Navigasi)','Background header dan menu'],['headerTagline','Warna Tagline Header','Teks kecil pada baris atas header'],['heroEyebrow','Warna Label Hero','Label kecil di atas judul hero'],['heroTitle','Warna Judul Hero','Judul besar di foto slider'],['heroText','Warna Deskripsi Hero','Teks deskripsi di bawah judul'],['heroButton','Warna Tombol Hero','Teks dan border tombol katalog'],['featureIconText','Warna Icon & Teks Feature','Warna umum feature (fallback)'],['featureHandIcon','Warna Icon Buatan Tangan','Warna ikon tangan'],['featureNaturalIcon','Warna Icon Bahan Alami','Warna ikon rotan/palm'],['featureQualityIcon','Warna Icon Kualitas','Warna ikon shield + check'],['featureCircle','Warna Lingkaran Icon','Warna outline lingkaran ikon'],['featureText','Warna Teks Feature','Warna judul dan keterangan feature'],['indicator','Warna Slide Indicator','Warna titik indicator'],['indicatorActive','Warna Slide Indicator Aktif','Warna titik slide aktif'],['pageBg','Warna Latar Halaman','Latar utama halaman pengunjung'],['sectionBg','Warna Latar Section','Latar section yang lebih lembut'],['border','Warna Border / Garis','Garis pemisah dan border']];document.getElementById('app').innerHTML=`<div class="panel"><div class="toolbar"><div><h2>Tampilan</h2><p class="sectionNote">Atur warna setiap bagian secara terpisah. Atur warna tiap icon, lingkaran, teks feature, dan slide indicator secara terpisah.</p></div><button class="btn" onclick="saveAppearance()">Simpan Tampilan</button></div><div class="colorGrid">${fields.map(([k,l,d])=>`<div class="colorField"><div><b>${l}</b><small>${d}</small></div><div class="colorControl"><input id="c_${k}" type="color" value="${html(a[k]||'#ffffff')}" oninput="document.getElementById('h_${k}').value=this.value"><input id="h_${k}" value="${html(a[k]||'#ffffff')}" maxlength=7 oninput="syncHexColor('${k}')"></div></div>`).join('')}</div><div class="panelNote"><b>Warna cepat</b><div class="swatches">${['#eadac5','#d9c6ae','#f5eee4','#8b6b4e','#211a15','#ffffff'].map(c=>`<button type="button" title="${c}" style="background:${c}" onclick="quickColor('${c}')"></button>`).join('')}</div></div></div>`}function syncHexColor(k){const h=document.getElementById('h_'+k),c=document.getElementById('c_'+k);if(!h||!c)return;let v=h.value.trim();if(/^#[0-9a-fA-F]{6}$/.test(v))c.value=v}function quickColor(c){['headerTagline','heroEyebrow','heroButton','featureIconText','featureHandIcon','featureNaturalIcon','featureQualityIcon','featureCircle','featureText','indicator','indicatorActive'].forEach(k=>{const h=document.getElementById('h_'+k),x=document.getElementById('c_'+k);if(h){h.value=c;x.value=c}})}async function saveAppearance(){const a=data.settings.appearance||{};['headerBg','headerTagline','heroEyebrow','heroTitle','heroText','heroButton','featureIconText','featureHandIcon','featureNaturalIcon','featureQualityIcon','featureCircle','featureText','indicator','indicatorActive','pageBg','sectionBg','border'].forEach(k=>{const v=document.getElementById('h_'+k)?.value.trim();if(/^#[0-9a-fA-F]{6}$/.test(v))a[k]=v.toLowerCase()});data.settings.appearance=a;safeLocalSave();try{await syncSiteSettings();alert('Tampilan tersimpan ke database production. Buka halaman pengunjung untuk melihat perubahan.')}catch(err){alert('Gagal sinkronisasi tampilan: '+err.message)}}
function media(){const imgs=data.products.map(p=>({src:p.image,name:p.name})).concat(data.hero.map((h,i)=>({src:h.image,name:'Hero '+(i+1)})));document.getElementById('app').innerHTML=`<div class="panel"><div class="toolbar"><div><h2>Media Library</h2><p class="sectionNote">Upload gambar dapat digunakan untuk Hero dan Produk. Demo menyimpan gambar di browser.</p></div><label class="upload">📷 Upload Media<input id="mediaInput" type="file" accept="image/*" multiple onchange="uploadMedia(event)"></label></div><div class="mediaGrid">${imgs.map(x=>`<div class="mediaCard"><img src="${x.src}"><div>${html(x.name)}</div></div>`).join('')}</div></div>`}function uploadMedia(e){const files=[...e.target.files];if(!files.length)return;alert(files.length+' file dipilih. Gunakan upload pada Hero/Produk untuk mengaitkan file ke konten. Media Library production akan menyimpan file ke server.');}
function channels(){document.getElementById('app').innerHTML=`<div class="panel"><div class="toolbar"><div><h2>Channel Penjualan</h2><p class="sectionNote">Hanya channel aktif dengan URL valid yang akan tampil di website pengunjung.</p></div></div>${(data.settings.channels||[]).map((c,i)=>`<div class="rule channelEdit"><div class="toolbar"><div><b>${html(c.name)}</b><p>${html(c.label||'')}</p></div><label><input id="ch${i}" type="checkbox" ${c.active?'checked':''}> Aktif</label></div><div class="formGrid"><input id="chn${i}" value="${html(c.label||c.name)}" placeholder="Label tombol"><input id="chu${i}" value="${html(c.url||'')}" placeholder="URL channel"><label><input id="cht${i}" type="checkbox" ${c.newTab!==false?'checked':''}> Buka di tab baru</label></div><div><label><input id="chs${i}" type="checkbox" ${c.positions?.includes('shop')?'checked':''}> Shop</label> <label><input id="chp${i}" type="checkbox" ${c.positions?.includes('product')?'checked':''}> Detail Produk</label> <label><input id="chf${i}" type="checkbox" ${c.positions?.includes('footer')?'checked':''}> Footer</label></div></div>`).join('')}<button class="btn" onclick="saveChannels()">Simpan Channel</button></div>`}async function saveChannels(){data.settings.channels.forEach((c,i)=>{c.active=$('#ch'+i).checked;c.label=$('#chn'+i).value.trim()||c.name;c.url=$('#chu'+i).value.trim();c.newTab=$('#cht'+i).checked;c.positions=[];if($('#chs'+i).checked)c.positions.push('shop');if($('#chp'+i).checked)c.positions.push('product');if($('#chf'+i).checked)c.positions.push('footer')});safeLocalSave();try{await syncSiteSettings();alert('Channel tersimpan ke database production.')}catch(err){alert('Gagal sinkronisasi channel: '+err.message)}}
function settings(){document.getElementById('app').innerHTML=`<div class="panel"><h2>Pengaturan Bisnis</h2><div class="formGrid"><input id="sb" value="${html(data.settings.brand)}" placeholder="Nama bisnis"><select id="sc"><option ${data.settings.currency==='USD'?'selected':''}>USD</option><option ${data.settings.currency==='IDR'?'selected':''}>IDR</option></select><input id="sw" value="${html(data.settings.whatsapp)}" placeholder="WhatsApp"><input id="se" value="${html(data.settings.email)}" placeholder="Email"><textarea id="sa" placeholder="Alamat">${html(data.settings.address)}</textarea><label>Konversi Admin: 1 USD = <input id="sr" type="number" min="1" step="1" value="${adminRate()}" style="max-width:180px"> IDR</label></div><button class="btn" onclick="saveSettings()">Simpan Pengaturan</button><p class="sectionNote">Dashboard Admin menampilkan seluruh nilai pesanan dalam IDR. Jika pesanan dibuat dalam USD, nilainya dikonversi otomatis menggunakan kurs Admin yang tersimpan. Mata uang pengunjung tetap independen (USD / IDR).</p></div>`}async function saveSettings(){Object.assign(data.settings,{brand:$('#sb').value,currency:$('#sc').value,whatsapp:$('#sw').value,email:$('#se').value,address:$('#sa').value,usdToIdrRate:Number($('#sr').value)||16000,adminDisplayCurrency:'IDR'});try{await apiFetch('/api/admin/settings',{method:'PATCH',body:JSON.stringify({brand:data.settings.brand,currency:data.settings.currency,whatsapp:data.settings.whatsapp,email:data.settings.email,address:data.settings.address,usdToIdrRate:data.settings.usdToIdrRate,adminDisplayCurrency:'IDR'})});await syncSiteSettings();alert('Pengaturan tersimpan ke database production.');render('settings')}catch(err){alert('Gagal menyimpan pengaturan: '+err.message);safeLocalSave()}}

async function loadProductionData(){try{const [pr,or,st]=await Promise.all([apiFetch('/api/products'),apiFetch('/api/admin/orders'),apiFetch('/api/admin/settings')]);data.products=(pr.products||[]).map(p=>({id:p.id,name:p.name_id||p.name_en||p.id,category:p.category||'home',type:p.type||'retail',stock:Number(p.stock)||0,moq:Number(p.moq)||1,price:Number(p.price_usd)||0,prices:{IDR:Number(p.price_idr)||0,USD:Number(p.price_usd)||0},image:p.image_key?('../'+p.image_key.replace(/^assets\//,'')):p.image||'',description:p.description_id||p.description_en||'',weight:Number(p.weight_kg)||0,dimensions:p.dimensions_cm||''}));data.orders=(or.orders||[]).map(o=>({id:o.order_number||o.id,currency:o.original_currency,total:Number(o.total_amount)||0,paymentStatus:o.payment_status||'PENDING',orderStatus:o.order_status||'NEW',customer:{first:[o.first_name,o.last_name].filter(Boolean).join(' ')||'—',country:o.shipping_address_json?((()=>{try{return JSON.parse(o.shipping_address_json).country||''}catch(_){return ''}})()):''}}));if(st.settings){Object.assign(data.settings,st.settings);data.settings.usdToIdrRate=Number(data.settings.usdToIdrRate)||16000;data.settings.adminDisplayCurrency='IDR';if(st.settings.homepage){const h=st.settings.homepage;Object.assign(data,{taglineEN:h.taglineEN||data.taglineEN,taglineID:h.taglineID||data.taglineID,introEyebrowEN:h.introEyebrowEN||data.introEyebrowEN,introEyebrowID:h.introEyebrowID||data.introEyebrowID,showIntroEyebrow:h.showIntroEyebrow!==false});if(Array.isArray(h.hero))h.hero.forEach((x,i)=>{if(!data.hero[i])data.hero[i]={};Object.assign(data.hero[i],x)});if(Array.isArray(h.collections)){data.collections=h.collections.map((x,i)=>({...x,number:x.number||String(i+1).padStart(2,'0')}))}}}render(active)}catch(err){console.warn('Production API hydration failed:',err)}}function exportData(){const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='palma-rotan-data.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
render('overview');loadProductionData();
